class Solution {
    public String zigzagCode(String text, int rows) {
        if (rows == 1) return text;
        StringBuilder[] lines = new StringBuilder[rows];
        for (int q = 0; q < rows; q++) lines[q] = new StringBuilder();
        int r = 0, step = 1;
        for (char c : text.toCharArray()) {
            lines[r].append(c);
            if (r == 0) step = 1;
            else if (r == rows - 1) step = -1;
            r += step;
        }
        StringBuilder out = new StringBuilder();
        for (StringBuilder line : lines) out.append(line);
        return out.toString();
    }
}

