char* zigzagCode(char* text, int rows) {
    int n = strlen(text);
    char* out = malloc(n + 1);
    if (rows == 1) { memcpy(out, text, n + 1); return out; }
    int* rowOf = malloc(n * sizeof(int));
    int r = 0, step = 1, pos = 0;
    for (int k = 0; k < n; k++) {
        rowOf[k] = r;
        if (r == 0) step = 1;
        else if (r == rows - 1) step = -1;
        r += step;
    }
    for (int q = 0; q < rows; q++)
        for (int k = 0; k < n; k++) if (rowOf[k] == q) out[pos++] = text[k];
    out[pos] = '\0';
    free(rowOf);
    return out;
}

