class Solution {
    public String zigzagCode(String text, int rows) {
        int n = text.length();
        if (rows == 1 || rows >= n) return text;
        int cycle = 2 * (rows - 1);
        StringBuilder out = new StringBuilder();
        for (int r = 0; r < rows; r++)
            for (int start = 0; start < n; start += cycle) {
                if (start + r < n) out.append(text.charAt(start + r));
                if (r > 0 && r < rows - 1 && start + cycle - r < n) out.append(text.charAt(start + cycle - r));
            }
        return out.toString();
    }
}

